from langgraph.graph import Node

class SummarizerNode(Node):
    """Simple demo summarizer that truncates text to 200 characters."""

    def run(self, text: str) -> str:
        # Replace this with a real LLM summarizer when you want
        return text[:200]

from langgraph.graph import Node

class TranslatorNode(Node):
    """Dummy translator that prefixes text with target language."""

    def run(self, text: str, target_lang: str = "en") -> str:
        # Replace this with a real translator when you want
        return f"[{target_lang}] {text}"
